package com.franco.desco.application.campaignparticipant.service;import com.franco.desco.application.campaignparticipant.*;import com.franco.desco.application.campaignparticipant.port.in.CampaignParticipantUseCase;import com.franco.desco.application.campaignparticipant.port.out.CampaignParticipantPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.campaignparticipant.CampaignParticipantModels;
public final class CampaignParticipantApplicationService implements CampaignParticipantUseCase{private final CampaignParticipantPersistencePort p;public CampaignParticipantApplicationService(CampaignParticipantPersistencePort p){this.p=p;}public AppResult<PageResult<CampaignParticipantModels.Summary>>list(CampaignParticipantCommands.ListParticipants c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"PARTICIPANTES_LISTADOS","PARTICIPANTES_NO_LISTADOS",AppStatus.BAD_REQUEST);}public AppResult<CampaignParticipantModels.Detail>get(CampaignParticipantCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"PARTICIPANTE_CONSULTADO","PARTICIPANTE_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>include(CampaignParticipantCommands.Include c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.include(c,i,m),"PARTICIPANTE_INCLUIDO","PARTICIPANTE_NO_INCLUIDO");}public AppResult<Long>program(CampaignParticipantCommands.Program c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.program(c,i,m),"PARTICIPANTE_PROGRAMADO","PARTICIPANTE_NO_PROGRAMADO");}public AppResult<Void>remove(CampaignParticipantCommands.Remove c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.remove(c,i,m),"PARTICIPANTE_RETIRADO","PARTICIPANTE_NO_RETIRADO",AppStatus.BAD_REQUEST);}}
